import { MedusaService } from "@medusajs/framework/utils"

import Brand from "./models/brand"

/**
 * The Brand Module owns the `brand` table and nothing else.
 *
 * Every method is generated by `MedusaService` from the model. The module
 * deliberately has no hand-written methods: the invariants that matter
 * (`handle` uniqueness, one brand per product) are enforced where they can be
 * trusted — a unique index for the first, and the link-assignment workflow for
 * the second.
 */
class BrandModuleService extends MedusaService({ Brand }) {}

export default BrandModuleService
